{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_015aXYK5SkL3QbhnbogMjtYH","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"\\\\\\\"\\\\\\\"\\\\\\\"\\\\nPrecompute (obs_features, action_variance) pairs for UncertaintyHead training.\\\\n\\\\nMode A (--mode cache): extract from existing K=10 precomputed cache\\\\n  Reads obs_features.pt and k_samples.pt directly.\\\\n\\\\nMode B (--mode sample): run SmolVLA inference to generate K samples per timestep\\\\n  Loads LIBERO demos, runs SmolVLA encode_prefix + K-sample generation.\\\\n\\\\nOutput: single .pt file with {obs_features, action_variance, task_names}\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\nimport argparse\\\\nimport sys\\\\nfrom pathlib import Path\\\\n\\\\nimport torch\\\\nimport numpy as np\\\\nfrom tqdm import tqdm\\\\n\\\\nsys.path.insert(0, str(Path(__file__).resolve().parent))\\\\nfrom utils import (\\\\n    load_libero_demos, OBS_DIM, FULL_ACTION_DIM, CORRECTION_DIM, H_EFF,\\\\n)\\\\n\\\\n\\\\ndef compute_variance_from_samples(samples):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Compute per-timestep action variance from K samples.\\\\n\\\\n    Args:\\\\n        samples: (N, K, H, D) action samples\\\\n    Returns:\\\\n        variance: (N,) scalar variance per timestep\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    N, K = samples.shape[:2]\\\\n    flat = samples.reshape(N, K, -1)  # (N, K, H*D)\\\\n    return flat.std(dim=1).mean(dim=1)  # (N,)\\\\n\\\\n\\\\ndef mode_cache(args):\\\\n    cache_dir = Path(args.cache_dir)\\\\n    obs_feat = torch.load(cache_dir / \\\\\\\"obs_features.pt\\\\\\\", map_location=\\\\\\\"cpu\\\\\\\", weights_only=True)\\\\n    k_samples = torch.load(cache_dir / \\\\\\\"k_samples.pt\\\\\\\", map_location=\\\\\\\"cpu\\\\\\\", weights_only=True)\\\\n    print(f\\\\\\\"Loaded cache: obs_features {obs_feat.shape}, k_samples {k_samples.shape}\\\\\\\")\\\\n\\\\n    variance = compute_variance_from_samples(k_samples)\\\\n\\\\n    task_names_path = cache_dir / \\\\\\\"task_names.pt\\\\\\\"\\\\n    if task_names_path.exists():\\\\n        task_names = torch.load(task_names_path, map_location=\\\\\\\"cpu\\\\\\\", weights_only=False)\\\\n    else:\\\\n        task_names = [\\\\\\\"unknown\\\\\\\"] * obs_feat.shape[0]\\\\n        print(\\\\\\\"Warning: task_names.pt not found, using 'unknown'\\\\\\\")\\\\n\\\\n    return obs_feat, variance, task_names\\\\n\\\\n\\\\ndef mode_sample(args):\\\\n    from smolvla_wrapper import SmolVLAWrapper\\\\n\\\\n    device = args.device\\\\n    K = args.K\\\\n\\\\n    print(f\\\\\\\"Loading SmolVLA from {args.smolvla_path}...\\\\\\\")\\\\n    vla = SmolVLAWrapper(pretrained_path=args.smolvla_path, device=device)\\\\n\\\\n    print(f\\\\\\\"Loading demos for benchmark={args.benchmark}...\\\\\\\")\\\\n    trajectories = load_libero_demos(args.benchmark, data_dir=args.data_dir)\\\\n    print(f\\\\\\\"Loaded {len(trajectories)} trajectories\\\\\\\")\\\\n\\\\n    all_obs_features = []\\\\n    all_variances = []\\\\n    all_task_names = []\\\\n\\\\n    for traj_idx, traj in enumerate(tqdm(trajectories, desc=\\\\\\\"Trajectories\\\\\\\")):\\\\n        T = traj[\\\\\\\"agentview_rgb\\\\\\\"].shape[0]\\\\n        task_name = traj[\\\\\\\"task_name\\\\\\\"]\\\\n\\\\n        for t in range(T):\\\\n            obs_feat, samples = vla.get_obs_features_and_samples(\\\\n                agentview_rgb=traj[\\\\\\\"agentview_rgb\\\\\\\"][t],\\\\n                task_name=task_name,\\\\n                robot_state=traj[\\\\\\\"ee_states\\\\\\\"][t],\\\\n                eye_in_hand_rgb=traj[\\\\\\\"eye_in_hand_rgb\\\\\\\"][t],\\\\n                K=K,\\\\n            )\\\\n            # obs_feat: (1, OBS_DIM), samples: (1, K, CHUNK_SIZE, FULL_ACTION_DIM)\\\\n            # Truncate to H_EFF and CORRECTION_DIM\\\\n            samples_trunc = samples[:, :, :H_EFF, :CORRECTION_DIM]  # (1, K, 5, 6)\\\\n\\\\n            var = compute_variance_from_samples(samples_trunc)  # (1,)\\\\n            all_obs_features.append(obs_feat.cpu())\\\\n            all_variances.append(var.cpu())\\\\n            all_task_names.append(task_name)\\\\n\\\\n    obs_features = torch.cat(all_obs_features, dim=0)  # (N, 960)\\\\n    variances = torch.cat(all_variances, dim=0)  # (N,)\\\\n    return obs_features, variances, all_task_names\\\\n\\\\n\\\\n\\\\ndef mode_per_sample(args):\\\\n    import glob\\\\n    cache_dir = Path(args.cache_dir)\\\\n    cache_files = sorted(glob.glob(str(cache_dir / '*.pt')))\\\\n    print(f'Found {len(cache_files)} cache files in {cache_dir}')\\\\n\\\\n    obs_list, var_list, task_list = [], [], []\\\\n    for i, f in enumerate(tqdm(cache_files, desc='Loading per-sample cache')):\\\\n        d = torch.load(f, map_location='cpu', weights_only=False)\\\\n        obs_list.append(d['obs_features'])  # (960,)\\\\n        vla = d['vla_action'].reshape(-1)   # (30,)\\\\n        expert = d['expert_action'].reshape(-1)  # (30,)\\\\n        deviation = (vla - expert).norm().item()\\\\n        var_list.append(deviation)\\\\n        task_list.append(d['task_name'])\\\\n\\\\n    obs_features = torch.stack(obs_list)  # (N, 960)\\\\n    variance = torch.tensor(var_list)     # (N,)\\\\n    return obs_features, variance, task_list\\\\n\\\\n\\\\ndef main():\\\\n    parser = argparse.ArgumentParser(description=\\\\\\\"Precompute uncertainty labels\\\\\\\")\\\\n    parser.add_argument(\\\\\\\"--benchmark\\\\\\\", type=str, required=True,\\\\n                        choices=[\\\\\\\"spatial\\\\\\\", \\\\\\\"object\\\\\\\", \\\\\\\"goal\\\\\\\", \\\\\\\"long\\\\\\\", \\\\\\\"90\\\\\\\"])\\\\n    parser.add_argument(\\\\\\\"--mode\\\\\\\", type=str, required=True, choices=[\\\\\\\"cache\\\\\\\", \\\\\\\"sample\\\\\\\", \\\\\\\"per_sample\\\\\\\"])\\\\n    parser.add_argument(\\\\\\\"--cache_dir\\\\\\\", type=str, default=\\\\\\\"/root/autodl-tmp/crm_cache/spatial/\\\\\\\")\\\\n    parser.add_argument(\\\\\\\"--output_file\\\\\\\", type=str, required=True)\\\\n    