es\\\")\\n\\n    all_obs_features = []\\n    all_variances = []\\n    all_task_names = []\\n\\n    for traj_idx, traj in enumerate(tqdm(trajectories, desc=\\\"Trajectories\\\")):\\n        T = traj[\\\"agentview_rgb\\\"].shape[0]\\n        task_name = traj[\\\"task_name\\\"]\\n\\n        for t in range(T):\\n            obs_feat, samples = vla.get_obs_features_and_samples(\\n                agentview_rgb=traj[\\\"agentview_rgb\\\"][t],\\n                task_name=task_name,\\n                robot_state=traj[\\\"ee_states\\\"][t],\\n                eye_in_hand_rgb=traj[\\\"eye_in_hand_rgb\\\"][t],\\n                K=K,\\n            )\\n            # obs_feat: (1, OBS_DIM), samples: (1, K, CHUNK_SIZE, FULL_ACTION_DIM)\\n            # Truncate to H_EFF and CORRECTION_DIM\\n            samples_trunc = samples[:, :, :H_EFF, :CORRECTION_DIM]  # (1, K, 5, 6)\\n\\n            var = compute_variance_from_samples(samples_trunc)  # (1,)\\n            all_obs_features.append(obs_feat.cpu())\\n            all_variances.append(var.cpu())\\n            all_task_names.append(task_name)\\n\\n    obs_features = torch.cat(all_obs_features, dim=0)  # (N, 960)\\n    variances = torch.cat(all_variances, dim=0)  # (N,)\\n    return obs_features, variances, all_task_names\\n\\n\\n\\ndef mode_per_sample(args):\\n    import glob\\n    cache_dir = Path(args.cache_dir)\\n    cache_files = sorted(glob.glob(str(cache_dir / '*.pt')))\\n    print(f'Found {len(cache_files)} cache files in {cache_dir}')\\n\\n    obs_list, var_list, task_list = [], [], []\\n    for i, f in enumerate(tqdm(cache_files, desc='Loading per-sample cache')):\\n        d = torch.load(f, map_location='cpu', weights_only=False)\\n        obs_list.append(d['obs_features'])  # (960,)\\n        vla = d['vla_action'].reshape(-1)   # (30,)\\n        expert = d['expert_action'].reshape(-1)  # (30,)\\n        deviation = (vla - expert).norm().item()\\n        var_list.append(deviation)\\n        task_list.append(d['task_name'])\\n